package main
import("bytes";"encoding/json";"net/http";"net/http/httptest";"os";"strings";"time")
type fixture struct{Body,Method string;Headers map[string]string}
func main(){var fs []fixture;if e:=json.NewDecoder(os.Stdin).Decode(&fs);e!=nil{panic(e)};out:=[]any{};for _,f:=range fs{r:=httptest.NewRequest(f.Method,"http://internal/attachment",nil);for k,v:=range f.Headers{r.Header.Set(k,v)};w:=httptest.NewRecorder();w.Header().Set("Content-Type","text/plain");w.Header().Set("Cache-Control","no-store");w.Header().Set("Content-Disposition","attachment");http.ServeContent(w,r,"file",time.Time{},bytes.NewReader([]byte(f.Body)));headers:=map[string]string{};body:=w.Body.String();for k,v:=range w.Result().Header{headers[strings.ToLower(k)]=v[0]};if value:=headers["content-type"];strings.HasPrefix(value,"multipart/byteranges; boundary="){boundary:=strings.TrimPrefix(value,"multipart/byteranges; boundary=");body=strings.ReplaceAll(body,boundary,strings.Repeat("x",60));headers["content-type"]="multipart/byteranges; boundary="+strings.Repeat("x",60)};out=append(out,map[string]any{"status":w.Code,"body":body,"headers":headers})};json.NewEncoder(os.Stdout).Encode(out)}
